<section class="page-heading"><span class="eyebrow">GOOD FOOD IS BETTER SHARED</span><h1>Customer reviews</h1><p>Tell your neighbors about the dishes you loved.</p></section>
<section class="section two-column"><div class="panel" data-reviews></div><form class="panel form-stack" data-review-form><h2>Leave a review</h2><label>Dish<select name="product_id" data-review-products required></select></label><label>Rating<select name="rating"><option value="5">5 stars</option><option value="4">4 stars</option><option value="3">3 stars</option><option value="2">2 stars</option><option value="1">1 star</option></select></label><label>Your review<textarea name="review" minlength="5" maxlength="2000" required></textarea></label><p class="form-message" data-message></p><button class="button">Submit review</button></form></section>
